244	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
245	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
246	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
247		top, ok, lerr := decodeTopValue(line)
248		if lerr != nil {
249			return nil, lerr
250		}
251		if ok != '[' {
252			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
253		}
254		var items []json.RawMessage
255		if err := json.Unmarshal(top, &items); err != nil {
256			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
257		}
258		return s.ingestItems(items)
259	}
