261	// QueryLine 解析并执行一行 op 为 "query" 的区间均值查询对象。成功返回 QueryResult；
262	// 查询只读，不改变存储。op 为 "query_points" 的采样明细查询由 QueryPointsLine
263	// 执行，op 为 "query_windows" 的固定窗口均值查询由 QueryWindowsLine 执行。
264	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
265		top, ok, lerr := decodeTopValue(line)
266		if lerr != nil {
267			return nil, lerr
268		}
269		if ok != '{' {
270			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
271		}
272		res, lerr := s.queryFromObject(top)
273		if lerr != nil {
274			return nil, lerr
275		}
276		qr, isQuery := res.(*QueryResult)
277		if !isQuery {
278			if _, isPoints := res.(*QueryPointsResult); isPoints {
279				return nil, &LineError{Status: "error", Error: `op "query_points" lists sample points; use QueryPointsLine`}
280			}
281			return nil, &LineError{Status: "error", Error: `op "query_windows" lists fixed-window averages; use QueryWindowsLine`}
282		}
283		return qr, nil
284	}
